extends SceneTree
func slab(sx: int, sy: int, px: int, py: int, bx0: int, by0: int, bx1: int, by1: int) -> bool:
	# doubled coordinates already; box closed [bx0,bx1]x[by0,by1]; returns true if blocked
	var lo_n: int = 0
	var lo_d: int = 1
	var hi_n: int = 1
	var hi_d: int = 1
	# x axis
	var dx: int = px - sx
	if dx == 0:
		if sx < bx0 or sx > bx1:
			return false
	else:
		var en: int
		var ex: int
		var den: int
		if dx > 0:
			en = bx0 - sx
			ex = bx1 - sx
			den = dx
		else:
			en = sx - bx1
			ex = sx - bx0
			den = -dx
		if en * lo_d > lo_n * den:
			lo_n = en
			lo_d = den
		if ex * hi_d < hi_n * den:
			hi_n = ex
			hi_d = den
	var dy: int = py - sy
	if dy == 0:
		if sy < by0 or sy > by1:
			return false
	else:
		var en2: int
		var ex2: int
		var den2: int
		if dy > 0:
			en2 = by0 - sy
			ex2 = by1 - sy
			den2 = dy
		else:
			en2 = sy - by1
			ex2 = sy - by0
			den2 = -dy
		if en2 * lo_d > lo_n * den2:
			lo_n = en2
			lo_d = den2
		if ex2 * hi_d < hi_n * den2:
			hi_n = ex2
			hi_d = den2
	return lo_n * hi_d <= hi_n * lo_d

func sat(sx: int, sy: int, px: int, py: int, bx0: int, by0: int, bx1: int, by1: int) -> bool:
	# bbox overlap (closed)
	if maxi(sx, px) < bx0 or mini(sx, px) > bx1 or maxi(sy, py) < by0 or mini(sy, py) > by1:
		return false
	var dx: int = px - sx
	var dy: int = py - sy
	var pos: int = 0
	var neg: int = 0
	for c in [[bx0, by0], [bx1, by0], [bx0, by1], [bx1, by1]]:
		var cr: int = dx * (c[1] - sy) - dy * (c[0] - sx)
		if cr > 0: pos += 1
		elif cr < 0: neg += 1
	return pos < 4 and neg < 4

func isqrt(d2: int, hi: int) -> int:
	var lo: int = 0
	var h: int = hi
	while lo < h:
		var mid: int = (lo + h + 1) >> 1
		if mid * mid <= d2:
			lo = mid
		else:
			h = mid - 1
	return lo

func _init() -> void:
	var rng: RandomNumberGenerator = RandomNumberGenerator.new()
	rng.seed = 17
	var mism: int = 0
	var blocked: int = 0
	var touch: int = 0
	var n: int = 300000
	for i in range(n):
		var sx: int = rng.randi_range(-40, 40) * 2
		var sy: int = rng.randi_range(-40, 40) * 2
		var px: int = rng.randi_range(-40, 40) * 2
		var py: int = rng.randi_range(-40, 40) * 2
		var x0: int = rng.randi_range(-30, 30)
		var y0: int = rng.randi_range(-30, 30)
		var x1: int = x0 + rng.randi_range(1, 12)
		var y1: int = y0 + rng.randi_range(1, 12)
		var b: Array = [2 * x0 - 1, 2 * y0 - 1, 2 * x1 - 1, 2 * y1 - 1]
		var a1: bool = slab(sx, sy, px, py, b[0], b[1], b[2], b[3])
		var a2: bool = sat(sx, sy, px, py, b[0], b[1], b[2], b[3])
		if a1 != a2:
			mism += 1
		if a1: blocked += 1
	print("slab vs SAT mismatches: ", mism, " of ", n, " blocked=", blocked)
	# seam leak example from GDD: S(23,300) P(24,140) vs boxes [-1,47]x[479,527]
	print("seam leak blocked: ", slab(46, 600, 48, 280, -1, 479, 47, 527))
	# isqrt vs exact
	var bad: int = 0
	for d2 in range(0, 147457):
		var r: int = isqrt(d2, 384)
		if r * r > d2 or (r + 1) * (r + 1) <= d2:
			bad += 1
	print("isqrt bad: ", bad)
	# DIR table checks
	var ux: PackedInt32Array = DirTable.UX
	var uy: PackedInt32Array = DirTable.UY
	var mm: int = 0
	for a in range(0, 4096):
		var m: int = (2048 - a) & 4095
		if ux[m] != -ux[a] or uy[m] != uy[a]:
			mm += 1
	print("mirror mismatches: ", mm, " size ", ux.size())
	var maxerr: int = 0
	for a in range(0, 4096):
		var n2: int = ux[a] * ux[a] + uy[a] * uy[a]
		maxerr = maxi(maxerr, absi(n2 - 268435456))
	print("max |norm2 - 2^28|: ", maxerr)
	for h in [341, 137, 114, 683, 228]:
		var c: int = ux[h]
		print("half ", h, " cosQ14 ", c, " COS2_Q28 ", c * c)
	# split wedge: 2*206 - 2*114
	print("wedge ", 2 * 206 - 2 * 114)
	# timings (editor binary, indicative)
	var t0: int = Time.get_ticks_usec()
	var acc: int = 0
	for i in range(200000):
		acc += isqrt(i & 0x1FFFF, 384)
	var t1: int = Time.get_ticks_usec()
	print("isqrt 200k us: ", t1 - t0, " per call ns ", (t1 - t0) * 1000 / 200000)
	t0 = Time.get_ticks_usec()
	for i in range(200000):
		if slab(46, 600, 48 + (i & 7), 280, -1, 479, 47, 527):
			acc += 1
	t1 = Time.get_ticks_usec()
	print("slab 200k us: ", t1 - t0, " per call ns ", (t1 - t0) * 1000 / 200000)
	t0 = Time.get_ticks_usec()
	for i in range(200000):
		var rx: int = (i & 255) - 128
		var ry: int = ((i >> 3) & 255) - 128
		var D: int = rx * ux[(i & 4095)] + ry * uy[(i & 4095)]
		var d2: int = rx * rx + ry * ry
		if d2 <= 82944 and D > 0 and D * D >= d2 * 201441249:
			acc += 1
	t1 = Time.get_ticks_usec()
	print("cone 200k us: ", t1 - t0, " per call ns ", (t1 - t0) * 1000 / 200000, " acc ", acc)
	quit()
